-- DRAFT: 独立节点库；所有正文均是客户端生成的密文。
PRAGMA foreign_keys = ON;
BEGIN IMMEDIATE;
CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY CHECK(version > 0), checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE devices (device_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, credential BLOB NOT NULL, endpoint_id TEXT NOT NULL, credential_version INTEGER NOT NULL CHECK(credential_version >= 0), state TEXT NOT NULL CHECK(state IN ('active','revoked')));
CREATE TABLE signed_discovery_records (device_id TEXT PRIMARY KEY REFERENCES devices(device_id), version INTEGER NOT NULL CHECK(version >= 0), signed_record BLOB NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE auth_challenges (challenge_id TEXT PRIMARY KEY, nonce_hash BLOB NOT NULL UNIQUE, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE TABLE key_packages (package_hash BLOB PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(device_id), public_package BLOB NOT NULL, expires_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('available','claimed','expired')), claim_request_id TEXT, claim_actor TEXT);
CREATE TABLE groups (group_id TEXT PRIMARY KEY, coordinator_id TEXT NOT NULL, owner_account_id TEXT NOT NULL, last_seq INTEGER NOT NULL CHECK(last_seq >= 0), last_hash BLOB NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','dissolved')));
CREATE TABLE group_members (group_id TEXT NOT NULL REFERENCES groups(group_id), device_id TEXT NOT NULL REFERENCES devices(device_id), account_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), muted INTEGER NOT NULL CHECK(muted IN (0,1)), joined_seq INTEGER NOT NULL CHECK(joined_seq >= 0), left_seq INTEGER, PRIMARY KEY(group_id, device_id, joined_seq));
CREATE TABLE group_control_heads (group_id TEXT PRIMARY KEY REFERENCES groups(group_id), control_head BLOB NOT NULL, policy_version INTEGER NOT NULL CHECK(policy_version >= 0), mls_epoch INTEGER NOT NULL CHECK(mls_epoch >= 0), public_policy BLOB NOT NULL);
CREATE TABLE group_log (group_id TEXT NOT NULL REFERENCES groups(group_id), group_seq INTEGER NOT NULL CHECK(group_seq > 0), submission_id TEXT NOT NULL, author_device_id TEXT NOT NULL REFERENCES devices(device_id), kind TEXT NOT NULL CHECK(kind IN ('application','control','delivery_receipt')), candidate_hash BLOB NOT NULL, previous_hash BLOB NOT NULL, log_hash BLOB NOT NULL, immutable_entry BLOB NOT NULL, signed_receipt BLOB NOT NULL, PRIMARY KEY(group_id, group_seq), UNIQUE(group_id, submission_id));
CREATE TABLE mailbox_items (item_id TEXT PRIMARY KEY, target_device_id TEXT NOT NULL REFERENCES devices(device_id), sender_device_id TEXT NOT NULL REFERENCES devices(device_id), payload_hash BLOB NOT NULL, ciphertext_envelope BLOB NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size >= 0), expires_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('stored','consumed','expired')), ordinal INTEGER NOT NULL UNIQUE CHECK(ordinal > 0));
CREATE INDEX mailbox_page ON mailbox_items(target_device_id, state, ordinal);
CREATE TABLE blob_uploads (upload_id TEXT PRIMARY KEY, owner_device_id TEXT NOT NULL REFERENCES devices(device_id), operation_id TEXT NOT NULL, expected_cipher_bytes INTEGER NOT NULL CHECK(expected_cipher_bytes >= 0), expected_chunk_count INTEGER NOT NULL CHECK(expected_chunk_count > 0), expires_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('uploading','complete','expired','collecting')), UNIQUE(owner_device_id, operation_id));
CREATE TABLE blob_chunks (upload_id TEXT NOT NULL REFERENCES blob_uploads(upload_id), chunk_index INTEGER NOT NULL CHECK(chunk_index >= 0), cipher_hash BLOB NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size > 0), storage_ref TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('staged','committed')), PRIMARY KEY(upload_id, chunk_index));
CREATE TABLE blob_objects (blob_id TEXT PRIMARY KEY, upload_id TEXT NOT NULL UNIQUE REFERENCES blob_uploads(upload_id), cipher_manifest BLOB NOT NULL, owner_device_id TEXT NOT NULL REFERENCES devices(device_id), state TEXT NOT NULL CHECK(state IN ('published','collecting')));
CREATE TABLE quotas (owner_id TEXT NOT NULL, resource_kind TEXT NOT NULL, used_bytes INTEGER NOT NULL DEFAULT 0 CHECK(used_bytes >= 0), reserved_bytes INTEGER NOT NULL DEFAULT 0 CHECK(reserved_bytes >= 0), limit_bytes INTEGER NOT NULL CHECK(limit_bytes >= 0), PRIMARY KEY(owner_id, resource_kind), CHECK(used_bytes + reserved_bytes <= limit_bytes));
CREATE TABLE request_dedup (scope TEXT NOT NULL, request_id TEXT NOT NULL, request_hash BLOB NOT NULL, durable_result BLOB NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(scope, request_id));
CREATE TABLE node_jobs (job_id TEXT PRIMARY KEY, dedup_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, payload_ref TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','leased','complete','failed')), retry_at INTEGER NOT NULL, lease_until INTEGER, lease_version INTEGER NOT NULL DEFAULT 0 CHECK(lease_version >= 0));
CREATE TABLE capability_revocations (issuer_id TEXT NOT NULL, capability_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version >= 0), revoked_at INTEGER NOT NULL, PRIMARY KEY(issuer_id, capability_id));
COMMIT;
